-- The two checklists published on 2026-11-22: The Days You Spend in the
-- Hospital (Hospital Stay) and The Week You Hand In Your Notice (Resigning).
-- Generated by `python3 tools/checklists_sql.py --since 2026-11-22`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('the-days-you-spend-in-the-hospital', 'The Days You Spend in the Hospital', 'Open this if you are admitted for a few days and the hospital''s schedule has taken over yours. It covers the small things that make a stay bearable: what to pack, how to keep track of what you are told, and how to hold on to a piece of your own day.', 'Hospital Stay', '["Pack earplugs, a mask and a long cable — Sleep and a reachable phone are the two hardest things to get.", "Keep one notebook for everything you are told — Names, times and answers blur fast when you are tired.", "Write down your question before rounds — You get a few minutes, and a forgotten question waits a whole day.", "Ask who to call with a question later — Knowing the number takes the panic out of the evening.", "Get up and walk the hallway once a day — Moving a little is the fastest way to feel like yourself.", "Keep one thing from home in sight — A photo or your own blanket makes the room less of a place things happen to you.", "Pick one hour with no visitors — A quiet hour you chose is different from one you were given.", "Say when the pain is worse than you said — Staff can only work from the number you give them."]'::jsonb, 'as needed', array['Self-Care', 'Resilience', 'Body']::text[], 1, '2026-11-22T16:00:00+00:00'::timestamptz),
  ('the-week-you-hand-in-your-notice', 'The Week You Hand In Your Notice', 'Open this in the days around telling your employer you are leaving, when the decision is made but saying it out loud still feels enormous. It helps you plan the conversation, keep it short and leave the door open behind you.', 'Resigning', '["Have the next thing in writing first — A signed offer turns a leap into a step.", "Tell your manager before anyone else — Hearing it secondhand is the one thing that sours a good exit.", "Write the resignation in three sentences — Short and warm beats a full explanation nobody asked for.", "Decide in advance what you will not explain — You owe them a date, not your reasons.", "Expect a counteroffer and know your answer — Deciding ahead stops a flattering number from undoing weeks of thought.", "List what only you know how to do — A short handoff note is the kindest thing you leave behind.", "Keep the last weeks boring on purpose — The reference you want is built in those final two weeks.", "Say a proper goodbye to two people — The colleagues you keep matter more than the job you left."]'::jsonb, 'as needed', array['Work', 'Life Transitions', 'Decision Making']::text[], 1, '2026-11-22T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
